import pytest
from starlette.datastructures import MutableHeaders


class TestMutableHeadersMergeOperators:
    """Tests for MutableHeaders | and |= operators (issue #...)."""

    def test_ior_with_dict(self):
        """|= with a dict should update headers in place."""
        headers = MutableHeaders()
        headers |= {"X-Header": "string"}
        assert "x-header" in headers
        assert headers["x-header"] == "string"
        assert dict(headers) == {"x-header": "string"}

    def test_ior_multiple_headers(self):
        """|= with multiple headers should add all."""
        headers = MutableHeaders()
        headers |= {"X-Header-1": "string-1", "X-Header-2": "string-2"}
        assert dict(headers) == {"x-header-1": "string-1", "x-header-2": "string-2"}

    def test_ior_overwrites_existing(self):
        """|= should overwrite existing header values."""
        headers = MutableHeaders()
        headers["x-header"] = "old"
        headers |= {"X-Header": "new"}
        assert headers["x-header"] == "new"
        assert len(headers) == 1  # no duplicate keys

    def test_ior_case_insensitive_overwrite(self):
        """|= should treat keys case-insensitively when overwriting."""
        headers = MutableHeaders()
        headers["X-Header"] = "old"
        headers |= {"x-header": "new"}
        assert headers["x-header"] == "new"
        assert headers["X-Header"] == "new"

    def test_ior_returns_self(self):
        """|= should return the same MutableHeaders instance."""
        headers = MutableHeaders()
        # Use __ior__ directly to capture the return value
        result = headers.__ior__({"a": "1"})
        assert result is headers

    def test_ior_empty_dict(self):
        """|= with empty dict should not change headers."""
        headers = MutableHeaders()
        headers["existing"] = "value"
        headers |= {}
        assert dict(headers) == {"existing": "value"}

    def test_or_returns_new_instance(self):
        """| should return a new MutableHeaders instance."""
        original = MutableHeaders()
        original["existing"] = "value"
        new_headers = original | {"new": "value"}
        assert new_headers is not original
        assert "new" in new_headers
        assert "new" not in original

    def test_or_does_not_modify_original(self):
        """| should not modify the original headers."""
        original = MutableHeaders()
        original["a"] = "1"
        original | {"b": "2"}
        assert dict(original) == {"a": "1"}

    def test_or_merges_correctly(self):
        """| should merge headers from both sides."""
        headers = MutableHeaders({"a": "1"})
        merged = headers | {"b": "2"}
        assert dict(merged) == {"a": "1", "b": "2"}

    def test_or_overwrites_existing(self):
        """| should overwrite existing keys with new values."""
        headers = MutableHeaders({"a": "old"})
        merged = headers | {"a": "new"}
        assert merged["a"] == "new"

    def test_or_returns_mutableheaders(self):
        """| should return a MutableHeaders instance."""
        headers = MutableHeaders()
        result = headers | {"a": "1"}
        assert isinstance(result, MutableHeaders)

    def test_consistency_with_update(self):
        """|= should produce the same result as .update()."""
        headers1 = MutableHeaders()
        headers1.update({"A": "1", "B": "2"})

        headers2 = MutableHeaders()
        headers2 |= {"A": "1", "B": "2"}

        assert dict(headers1) == dict(headers2)

    def test_ior_with_mutableheaders(self):
        """|= should also work with another MutableHeaders (via dict interface)."""
        headers1 = MutableHeaders({"a": "1"})
        headers2 = MutableHeaders({"b": "2"})
        headers1 |= headers2
        assert dict(headers1) == {"a": "1", "b": "2"}

    def test_or_with_mutableheaders(self):
        """| should also work with another MutableHeaders."""
        headers1 = MutableHeaders({"a": "1"})
        headers2 = MutableHeaders({"b": "2"})
        merged = headers1 | headers2
        assert dict(merged) == {"a": "1", "b": "2"}
        assert merged is not headers1
        assert merged is not headers2

    def test_ior_preserves_other_headers(self):
        """|= should keep headers not present in the merged dict."""
        headers = MutableHeaders({"keep": "me"})
        headers |= {"new": "header"}
        assert "keep" in headers
        assert headers["keep"] == "me"

    def test_or_preserves_original_headers(self):
        """| should keep all original headers in the new instance."""
        headers = MutableHeaders({"keep": "me"})
        merged = headers | {"new": "header"}
        assert "keep" in merged
        assert merged["keep"] == "me"

    def test_ior_with_non_dict_mapping(self):
        """|= should accept any Mapping (e.g., another MutableHeaders)."""
        headers = MutableHeaders()
        other = MutableHeaders({"x": "y"})
        headers |= other
        assert dict(headers) == {"x": "y"}

    def test_or_with_non_dict_mapping(self):
        """| should accept any Mapping."""
        headers = MutableHeaders()
        other = MutableHeaders({"x": "y"})
        merged = headers | other
        assert dict(merged) == {"x": "y"}

    def test_ior_handles_duplicate_keys_in_other(self):
        """|= should handle duplicate keys in the other dict (last wins)."""
        headers = MutableHeaders()
        headers |= {"a": "1", "a": "2"}  # duplicate key in dict
        assert headers["a"] == "2"

    def test_or_handles_duplicate_keys_in_other(self):
        """| should handle duplicate keys in the other dict (last wins)."""
        headers = MutableHeaders()
        merged = headers | {"a": "1", "a": "2"}
        assert merged["a"] == "2"

    def test_ior_after_initialization(self):
        """|= should work on a MutableHeaders initialized with headers."""
        headers = MutableHeaders({"existing": "value"})
        headers |= {"new": "value"}
        assert dict(headers) == {"existing": "value", "new": "value"}

    def test_or_after_initialization(self):
        """| should work on a MutableHeaders initialized with headers."""
        headers = MutableHeaders({"existing": "value"})
        merged = headers | {"new": "value"}
        assert dict(merged) == {"existing": "value", "new": "value"}
        assert dict(headers) == {"existing": "value"}  # unchanged

