"""Tests for the publish-lib exit code fix (issue #XXXX)."""

from unittest.mock import MagicMock, patch

import pytest
from craft_cli import emit

from charmcraft.application.commands.store import PublishLibCommand


@pytest.fixture(autouse=True)
def mock_emit():
    """Mock emit to capture messages and avoid side effects."""
    with patch.object(emit, "message") as mock_message, \
         patch.object(emit, "progress") as mock_progress:
        yield mock_message, mock_progress


@pytest.fixture
def mock_app():
    """Create a minimal mock app metadata."""
    app = MagicMock()
    app.name = "charmcraft"
    app.version = "test"
    return app


@pytest.fixture
def mock_services():
    """Create a mocked services object with a mocked store."""
    services = MagicMock()
    services.store = MagicMock()
    return services


@pytest.fixture
def command(mock_app, mock_services):
    """Create a PublishLibCommand instance with mocked dependencies."""
    config = {
        "app": mock_app,
        "services": mock_services,
    }
    cmd = PublishLibCommand(config)
    return cmd


def _make_lib_data(name="test-lib", api=0, patch=1, content_hash="abc"):
    """Helper to create a library data dict as expected by the command."""
    return {
        "lib_name": name,
        "api": api,
        "patch": patch,
        "content_hash": content_hash,
        "lib_path": f"lib/charms/{name}/v{api}/test.py",
    }


def _make_parsed_args(format=None):
    """Helper to create a Namespace-like object with format attribute."""
    args = MagicMock()
    args.format = format
    return args


class TestPublishLibExitCode:
    """Test that publish-lib returns correct exit codes."""

    def test_success_all_libraries(self, command, mock_services, mock_emit):
        """All libraries publish successfully -> exit code 0."""
        lib_data = [_make_lib_data(patch=2)]
        # Tip has lower patch -> ok
        mock_services.store.get_libraries_tips.return_value = {
            "test-lib": {"api": 0, "patch": 1}
        }
        mock_services.store.create_library_revision.return_value = None

        with patch.object(command, "_get_libraries_data", return_value=lib_data):
            result = command.run(_make_parsed_args())
        assert result is None or result == 0, "Expected exit code 0 on success"

    def test_failure_libpatch_not_bumped(self, command, mock_services, mock_emit):
        """Library fails because LIBPATCH is not bumped -> exit code 1."""
        lib_data = [_make_lib_data(patch=1)]
        # Tip has same patch -> error
        mock_services.store.get_libraries_tips.return_value = {
            "test-lib": {"api": 0, "patch": 1}
        }
        # create_library_revision should not be called
        mock_services.store.create_library_revision.side_effect = AssertionError(
            "Should not be called"
        )

        with patch.object(command, "_get_libraries_data", return_value=lib_data):
            result = command.run(_make_parsed_args())
        assert result == 1, "Expected exit code 1 on failure"

    def test_failure_libpatch_going_back(self, command, mock_services, mock_emit):
        """Library fails because LIBPATCH goes backwards -> exit code 1."""
        lib_data = [_make_lib_data(patch=1)]
        # Tip has higher patch -> going back
        mock_services.store.get_libraries_tips.return_value = {
            "test-lib": {"api": 0, "patch": 2}
        }

        with patch.object(command, "_get_libraries_data", return_value=lib_data):
            result = command.run(_make_parsed_args())
        assert result == 1, "Expected exit code 1 on failure"

    def test_mixed_success_and_failure(self, command, mock_services, mock_emit):
        """Some libraries succeed, some fail -> exit code 1."""
        lib_data = [
            _make_lib_data(name="lib-ok", patch=2),
            _make_lib_data(name="lib-fail", patch=1),
        ]
        mock_services.store.get_libraries_tips.return_value = {
            "lib-ok": {"api": 0, "patch": 1},   # ok
            "lib-fail": {"api": 0, "patch": 2},  # fail
        }
        mock_services.store.create_library_revision.return_value = None

        with patch.object(command, "_get_libraries_data", return_value=lib_data):
            result = command.run(_make_parsed_args())
        assert result == 1, "Expected exit code 1 on mixed results"

    def test_failure_with_json_format(self, command, mock_services, mock_emit):
        """Failure with --format=json still returns exit code 1."""
        lib_data = [_make_lib_data(patch=1)]
        mock_services.store.get_libraries_tips.return_value = {
            "test-lib": {"api": 0, "patch": 2}
        }

        with patch.object(command, "_get_libraries_data", return_value=lib_data):
            result = command.run(_make_parsed_args(format="json"))
        assert result == 1, "Expected exit code 1 even with JSON format"

    def test_success_with_json_format(self, command, mock_services, mock_emit):
        """Success with --format=json returns exit code 0."""
        lib_data = [_make_lib_data(patch=2)]
        mock_services.store.get_libraries_tips.return_value = {
            "test-lib": {"api": 0, "patch": 1}
        }
        mock_services.store.create_library_revision.return_value = None

        with patch.object(command, "_get_libraries_data", return_value=lib_data):
            result = command.run(_make_parsed_args(format="json"))
        assert result is None or result == 0, "Expected exit code 0 on success with JSON"

    def test_all_failures(self, command, mock_services, mock_emit):
        """All libraries fail -> exit code 1."""
        lib_data = [
            _make_lib_data(name="lib1", patch=1),
            _make_lib_data(name="lib2", patch=1),
        ]
        mock_services.store.get_libraries_tips.return_value = {
            "lib1": {"api": 0, "patch": 2},
            "lib2": {"api": 0, "patch": 2},
        }

        with patch.object(command, "_get_libraries_data", return_value=lib_data):
            result = command.run(_make_parsed_args())
        assert result == 1, "Expected exit code 1 when all fail"

    def test_no_libraries(self, command, mock_services, mock_emit):
        """No libraries to publish -> exit code 0 (nothing to fail)."""
        with patch.object(command, "_get_libraries_data", return_value=[]):
            result = command.run(_make_parsed_args())
        assert result is None or result == 0, "Expected exit code 0 when no libraries"

import pytest

from starlette.datastructures import MutableHeaders


class TestMutableHeadersOperators:
    """Tests for the | and |= operators on MutableHeaders."""

    def test_ior_with_dict(self):
        """Test the exact example from the issue: response |= {"X-Header": "string"}"""
        headers = MutableHeaders()
        headers |= {"X-Header": "string"}
        assert "x-header" in headers
        assert headers["x-header"] == "string"
        assert dict(headers) == {"x-header": "string"}

    def test_ior_modifies_in_place(self):
        """|= should modify the original object and return self."""
        headers = MutableHeaders()
        headers["existing"] = "value"
        original_id = id(headers)
        headers |= {"new": "value"}
        # The |= operator returns self, but we can't capture it in an assignment.
        # Instead, verify that the original object was modified.
        assert id(headers) == original_id
        assert "new" in headers

    def test_or_returns_new_instance(self):
        """| should return a new MutableHeaders without modifying the original."""
        original = MutableHeaders()
        original["existing"] = "value"
        original_id = id(original)
        new_headers = original | {"new": "value"}
        assert new_headers is not original
        assert id(original) == original_id
        assert "new" in new_headers
        assert "new" not in original

    def test_or_preserves_original(self):
        """Original headers should be unchanged after |."""
        original = MutableHeaders()
        original["a"] = "1"
        original | {"b": "2"}
        assert dict(original) == {"a": "1"}

    def test_ior_consistency_with_update(self):
        """|= should produce the same result as .update()."""
        headers1 = MutableHeaders()
        headers1.update({"A": "1", "B": "2"})

        headers2 = MutableHeaders()
        headers2 |= {"A": "1", "B": "2"}

        assert dict(headers1) == dict(headers2)
        assert repr(headers1) == repr(headers2)

    def test_or_consistency_with_update(self):
        """| should produce the same result as creating a copy and updating."""
        original = MutableHeaders()
        original["a"] = "1"

        # Using |
        merged = original | {"b": "2"}

        # Manual copy + update
        expected = original.mutablecopy()
        expected.update({"b": "2"})

        assert dict(merged) == dict(expected)

    def test_ior_with_empty_dict(self):
        """|= with an empty dict should not change anything."""
        headers = MutableHeaders()
        headers["a"] = "1"
        headers |= {}
        assert dict(headers) == {"a": "1"}

    def test_or_with_empty_dict(self):
        """| with an empty dict should return a copy."""
        original = MutableHeaders()
        original["a"] = "1"
        result = original | {}
        assert dict(result) == {"a": "1"}
        assert result is not original

    def test_ior_overwrites_existing_keys(self):
        """|= should overwrite existing keys (case-insensitive)."""
        headers = MutableHeaders()
        headers["X-Header"] = "old"
        headers |= {"x-header": "new"}
        assert headers["x-header"] == "new"
        assert len(headers) == 1  # no duplicate

    def test_or_overwrites_existing_keys(self):
        """| should overwrite existing keys (case-insensitive)."""
        original = MutableHeaders()
        original["X-Header"] = "old"
        result = original | {"x-header": "new"}
        assert result["x-header"] == "new"
        assert len(result) == 1

    def test_ior_multiple_headers(self):
        """|= should handle multiple headers at once."""
        headers = MutableHeaders()
        headers |= {
            "X-Header-1": "string-1",
            "X-Header-2": "string-2",
            "X-Header-3": "string-3",
        }
        expected = {
            "x-header-1": "string-1",
            "x-header-2": "string-2",
            "x-header-3": "string-3",
        }
        assert dict(headers) == expected

    def test_or_multiple_headers(self):
        """| should handle multiple headers at once."""
        original = MutableHeaders()
        original["existing"] = "keep"
        result = original | {
            "X-Header-1": "string-1",
            "X-Header-2": "string-2",
        }
        expected = {
            "existing": "keep",
            "x-header-1": "string-1",
            "x-header-2": "string-2",
        }
        assert dict(result) == expected

    def test_ior_returns_self(self):
        """|= should return self to allow chaining (verify by checking object identity)."""
        headers = MutableHeaders()
        # We cannot capture the return value in an assignment, but we can check
        # that the operation works and the object is the same.
        headers_copy = headers
        headers |= {"a": "1"}
        assert headers is headers_copy

    def test_or_returns_new_type(self):
        """| should return a MutableHeaders instance."""
        headers = MutableHeaders()
        result = headers | {"a": "1"}
        assert isinstance(result, MutableHeaders)

import pytest

from starlette.datastructures import MutableHeaders


class TestMutableHeadersMergeOperators:
    """Tests for MutableHeaders | and |= operators (issue #??)."""

    def test_ior_with_dict(self):
        """|= should merge a dict into the headers."""
        headers = MutableHeaders()
        headers |= {"X-Header": "string"}
        assert headers["x-header"] == "string"
        assert dict(headers) == {"x-header": "string"}

    def test_ior_modifies_in_place(self):
        """|= should modify the original object and return self."""
        headers = MutableHeaders()
        headers["existing"] = "value"
        original_id = id(headers)
        headers |= {"new": "value"}
        assert id(headers) == original_id
        assert "new" in headers

    def test_ior_overwrites_existing(self):
        """|= should overwrite existing headers."""
        headers = MutableHeaders()
        headers["x-header"] = "old"
        headers |= {"X-Header": "new"}
        assert headers["x-header"] == "new"

    def test_ior_case_insensitive_overwrite(self):
        """|= should treat keys case-insensitively when overwriting."""
        headers = MutableHeaders()
        headers["X-Header"] = "old"
        headers |= {"x-header": "new"}
        assert headers["x-header"] == "new"

    def test_ior_multiple_headers(self):
        """|= should merge multiple headers at once."""
        headers = MutableHeaders()
        headers |= {
            "X-Header-1": "value1",
            "X-Header-2": "value2",
            "X-Header-3": "value3",
        }
        assert dict(headers) == {
            "x-header-1": "value1",
            "x-header-2": "value2",
            "x-header-3": "value3",
        }

    def test_ior_empty_dict(self):
        """|= with an empty dict should not change headers."""
        headers = MutableHeaders()
        headers["a"] = "1"
        headers |= {}
        assert dict(headers) == {"a": "1"}

    def test_ior_consistency_with_update(self):
        """|= should produce the same result as .update()."""
        headers1 = MutableHeaders()
        headers1.update({"A": "1", "B": "2"})

        headers2 = MutableHeaders()
        headers2 |= {"A": "1", "B": "2"}

        assert dict(headers1) == dict(headers2)

    def test_or_returns_new_instance(self):
        """| should return a new MutableHeaders without modifying the original."""
        original = MutableHeaders()
        original["existing"] = "value"
        original_id = id(original)
        new_headers = original | {"new": "value"}
        assert new_headers is not original
        assert id(original) == original_id
        assert "new" in new_headers
        assert "new" not in original

    def test_or_preserves_original(self):
        """| should not alter the original headers."""
        original = MutableHeaders()
        original["a"] = "1"
        original | {"b": "2"}
        assert dict(original) == {"a": "1"}

    def test_or_merges_correctly(self):
        """| should merge the dict into a copy."""
        headers = MutableHeaders()
        headers["a"] = "1"
        merged = headers | {"b": "2"}
        assert dict(merged) == {"a": "1", "b": "2"}

    def test_or_overwrites_existing(self):
        """| should overwrite existing keys in the new instance."""
        headers = MutableHeaders()
        headers["a"] = "old"
        merged = headers | {"A": "new"}
        assert merged["a"] == "new"

    def test_or_empty_dict(self):
        """| with an empty dict should return a copy."""
        headers = MutableHeaders()
        headers["a"] = "1"
        merged = headers | {}
        assert dict(merged) == {"a": "1"}
        assert merged is not headers

    def test_ior_returns_mutableheaders(self):
        """|= should return a MutableHeaders instance (the same object)."""
        headers = MutableHeaders()
        headers |= {"key": "value"}
        assert isinstance(headers, MutableHeaders)

    def test_or_returns_mutableheaders(self):
        """| should return a MutableHeaders instance."""
        headers = MutableHeaders()
        result = headers | {"key": "value"}
        assert isinstance(result, MutableHeaders)

    def test_or_chaining(self):
        """| should support chaining."""
        headers = MutableHeaders()
        headers["a"] = "1"
        merged = headers | {"b": "2"} | {"c": "3"}
        assert dict(merged) == {"a": "1", "b": "2", "c": "3"}
        assert dict(headers) == {"a": "1"}  # original unchanged

    def test_ior_with_another_mutableheaders(self):
        """|= should also work with another MutableHeaders (dict-like)."""
        headers1 = MutableHeaders()
        headers1["a"] = "1"
        headers2 = MutableHeaders()
        headers2["b"] = "2"
        headers1 |= headers2
        assert dict(headers1) == {"a": "1", "b": "2"}

    def test_or_with_another_mutableheaders(self):
        """| should also work with another MutableHeaders."""
        headers1 = MutableHeaders()
        headers1["a"] = "1"
        headers2 = MutableHeaders()
        headers2["b"] = "2"
        merged = headers1 | headers2
        assert dict(merged) == {"a": "1", "b": "2"}
        assert dict(headers1) == {"a": "1"}
        assert dict(headers2) == {"b": "2"}

