class TestGetValues:
    """Tests for Worksheet.get_values()"""

    def test_valid_kwargs(self, mock_worksheet):
        ws, client = mock_worksheet
        # Mock the underlying get() call (which itself calls client.values_get)
        # Provide a proper response with "range" key so ValueRange.from_json works
        client.values_get.return_value = {
            "range": "'Sheet1'!A1:B2",
            "majorDimension": "ROWS",
            "values": [["a", "b"], ["c", "d"]],
        }
        # Also mock fetch_sheet_metadata for combine_merged_cells=False (default)
        client.fetch_sheet_metadata.return_value = {"sheets": []}

        # Call with all explicit kwargs
        result = ws.get_values(
            range_name="A1:B2",
            major_dimension="ROWS",
            combine_merged_cells=False,
            value_render_option="FORMATTED_VALUE",
            date_time_render_option="SERIAL_NUMBER",
        )
        # Verify the underlying client call was made with the correct params
        client.values_get.assert_called_once_with(
            "test_spreadsheet_id",
            "'Sheet1'!A1:B2",
            params={
                "majorDimension": "ROWS",
                "valueRenderOption": "FORMATTED_VALUE",
                "dateTimeRenderOption": "SERIAL_NUMBER",
            },
        )
        assert result == [["a", "b"], ["c", "d"]]

