        ws, client = mock_worksheet
        # When range_name is None, absolute_range_name returns "'Sheet1'" (no !)
        client.values_get.return_value = {
            "range": "'Sheet1'",
            "majorDimension": "ROWS",
            "values": [["x"]],
        }
        client.fetch_sheet_metadata.return_value = {"sheets": []}

        # Call with no optional kwargs (they default to None)
        result = ws.get_values()
        # The params dict should contain None values (they will be ignored by API)
        client.values_get.assert_called_once_with(
            "test_spreadsheet_id",
            "'Sheet1'",
            params={
                "majorDimension": None,
                "valueRenderOption": None,
                "dateTimeRenderOption": None,
            },
        )
        assert result == [["x"]]

