class TestNoneValuesPassedThrough:
    """The old filter_dict_values removed None entries from the params dict.
    The new code should pass None values directly (the API will ignore them).
    """

    def test_get_params_contain_none(self, mock_worksheet):
        ws, client = mock_worksheet
        client.values_get.return_value = {
            "range": "'Sheet1'",
            "majorDimension": "ROWS",
            "values": [],
        }
        ws.get()
        # The params dict should have None values, not be filtered
        call_args = client.values_get.call_args
        params = call_args[1]["params"]
        assert "majorDimension" in params
        assert params["majorDimension"] is None
        assert "valueRenderOption" in params
        assert params["valueRenderOption"] is None
        assert "dateTimeRenderOption" in params
        assert params["dateTimeRenderOption"] is None

    def test_update_body_contains_none_major_dimension(self, mock_worksheet):
        ws, client = mock_worksheet
        client.values_update.return_value = {}
        ws.update("A1", [[1]])
        call_args = client.values_update.call_args
        body = call_args[1]["body"]
        # majorDimension should be None (not filtered out)
        assert "majorDimension" in body
        assert body["majorDimension"] is None
        # values should be present
        assert body["values"] == [[1]]

    def test_batch_update_body_contains_none_fields(self, mock_worksheet):
        ws, client = mock_worksheet
        client.values_batch_update.return_value = {}
        ws.batch_update([{"range": "A1", "values": [["x"]]}])
        call_args = client.values_batch_update.call_args
        body = call_args[1]["body"]
        # All optional fields should be present with None values
        assert "includeValuesInResponse" in body
        assert body["includeValuesInResponse"] is None
        assert "responseValueRenderOption" in body
        assert body["responseValueRenderOption"] is None
        assert "responseDateTimeRenderOption" in body
        assert body["responseDateTimeRenderOption"] is None
        # valueInputOption should be set (not None) because raw=True default
        assert body["valueInputOption"] == "RAW"

