        """Dollar signs should be escaped for mpv property expansion"""
        self._test_args(
            ["streamlink", "-p", "/usr/bin/mpv", "--title", "price is $10", "http://test.se", "test"],
            ["/usr/bin/mpv", "--title='price is $$10'", "-"]
        )

