import pytest

from jwt.api_jwt import PyJWT
from jwt.exceptions import InvalidAudienceError, MissingRequiredClaimError


class TestNullAudience:
    """Tests for handling of {"aud": null} in JWT payloads."""

    @pytest.fixture
    def jwt(self):
        return PyJWT()

    def test_aud_null_no_audience_expected(self, jwt):
        """aud=null and no audience provided → should succeed."""
        payload = {"some": "data", "aud": None}
        token = jwt.encode(payload, "secret")
        decoded = jwt.decode(token, "secret", algorithms=["HS256"])
        assert decoded["aud"] is None  # original value preserved

    def test_aud_null_audience_expected_raises(self, jwt):
        """aud=null but audience is required → MissingRequiredClaimError."""
        payload = {"some": "data", "aud": None}
        token = jwt.encode(payload, "secret")
        with pytest.raises(MissingRequiredClaimError) as exc_info:
            jwt.decode(token, "secret", audience="my_aud", algorithms=["HS256"])
        assert exc_info.value.claim == "aud"

    def test_aud_null_audience_list_expected_raises(self, jwt):
        """aud=null but audience list is required → MissingRequiredClaimError."""
        payload = {"some": "data", "aud": None}
        token = jwt.encode(payload, "secret")
        with pytest.raises(MissingRequiredClaimError) as exc_info:
            jwt.decode(token, "secret", audience=["a", "b"], algorithms=["HS256"])
        assert exc_info.value.claim == "aud"

    def test_aud_null_explicit_none_audience(self, jwt):
        """aud=null and audience=None explicitly → should succeed."""
        payload = {"some": "data", "aud": None}
        token = jwt.encode(payload, "secret")
        decoded = jwt.decode(token, "secret", audience=None, algorithms=["HS256"])
        assert decoded["aud"] is None

    def test_aud_null_verify_aud_disabled(self, jwt):
        """aud=null and verify_aud=False → should succeed even with audience."""
        payload = {"some": "data", "aud": None}
        token = jwt.encode(payload, "secret")
        decoded = jwt.decode(
            token,
            "secret",
            audience="my_aud",
            algorithms=["HS256"],
            options={"verify_aud": False},
        )
        assert decoded["aud"] is None

    def test_aud_valid_string_still_works(self, jwt):
        """Normal string aud still validated correctly."""
        payload = {"some": "data", "aud": "correct"}
        token = jwt.encode(payload, "secret")
        decoded = jwt.decode(token, "secret", audience="correct", algorithms=["HS256"])
        assert decoded["aud"] == "correct"

    def test_aud_valid_string_wrong_audience_raises(self, jwt):
        """Normal string aud with wrong audience → InvalidAudienceError."""
        payload = {"some": "data", "aud": "correct"}
        token = jwt.encode(payload, "secret")
        with pytest.raises(InvalidAudienceError):
            jwt.decode(token, "secret", audience="wrong", algorithms=["HS256"])

    def test_aud_valid_list_still_works(self, jwt):
        """Normal list aud still validated correctly."""
        payload = {"some": "data", "aud": ["a", "b"]}
        token = jwt.encode(payload, "secret")
        decoded = jwt.decode(token, "secret", audience="a", algorithms=["HS256"])
        assert decoded["aud"] == ["a", "b"]

    def test_aud_valid_list_wrong_audience_raises(self, jwt):
        """Normal list aud with wrong audience → InvalidAudienceError."""
        payload = {"some": "data", "aud": ["a", "b"]}
        token = jwt.encode(payload, "secret")
        with pytest.raises(InvalidAudienceError):
            jwt.decode(token, "secret", audience="c", algorithms=["HS256"])

    def test_aud_null_with_other_claims(self, jwt):
        """aud=null alongside other claims like exp, iss, etc."""
        payload = {"iss": "me", "exp": 9999999999, "aud": None}
        token = jwt.encode(payload, "secret")
        decoded = jwt.decode(
            token,
            "secret",
            issuer="me",
            algorithms=["HS256"],
            options={"verify_exp": False},
        )
        assert decoded["aud"] is None

    def test_aud_null_required_claim_not_affected(self, jwt):
        """If aud is in require list, aud=null should still be treated as missing."""
        payload = {"some": "data", "aud": None}
        token = jwt.encode(payload, "secret")
        with pytest.raises(MissingRequiredClaimError) as exc_info:
            jwt.decode(
                token,
                "secret",
                algorithms=["HS256"],
                options={"require": ["aud"]},
            )
        assert exc_info.value.claim == "aud"

    def test_no_aud_claim_still_works(self, jwt):
        """Token without aud claim still works as before."""
        payload = {"some": "data"}
        token = jwt.encode(payload, "secret")
        decoded = jwt.decode(token, "secret", algorithms=["HS256"])
        assert decoded == {"some": "data"}

    def test_no_aud_claim_audience_expected_raises(self, jwt):
        """Token without aud but audience required → MissingRequiredClaimError."""
        payload = {"some": "data"}
        token = jwt.encode(payload, "secret")
        with pytest.raises(MissingRequiredClaimError) as exc_info:
            jwt.decode(token, "secret", audience="x", algorithms=["HS256"])
        assert exc_info.value.claim == "aud"

import pytest

from jwt.api_jwt import PyJWT
from jwt.exceptions import InvalidAudienceError, MissingRequiredClaimError


class TestNullAudience:
    """Tests for handling of {"aud": null} in JWT payloads."""

    @pytest.fixture
    def jwt(self):
        return PyJWT()

    @pytest.fixture
    def secret(self):
        return "secret"

    # --- Core issue: null aud should be treated as absent ---

    def test_null_aud_without_audience_param(self, jwt, secret):
        """Token with {"aud": null} should decode successfully when no audience is expected."""
        payload = {"some": "payload", "aud": None}
        token = jwt.encode(payload, secret, algorithm="HS256")
        decoded = jwt.decode(token, secret, algorithms=["HS256"])
        assert decoded["some"] == "payload"
        # The returned payload still contains aud: None because the token itself has it
        assert decoded["aud"] is None

    def test_null_aud_with_explicit_none_audience(self, jwt, secret):
        """Token with {"aud": null} should decode successfully when audience=None is passed."""
        payload = {"some": "payload", "aud": None}
        token = jwt.encode(payload, secret, algorithm="HS256")
        decoded = jwt.decode(token, secret, audience=None, algorithms=["HS256"])
        assert decoded["some"] == "payload"

    def test_null_aud_with_audience_required_raises_missing(self, jwt, secret):
        """Token with {"aud": null} should raise MissingRequiredClaimError when audience is required."""
        payload = {"some": "payload", "aud": None}
        token = jwt.encode(payload, secret, algorithm="HS256")
        with pytest.raises(MissingRequiredClaimError) as exc_info:
            jwt.decode(token, secret, audience="urn:test", algorithms=["HS256"])
        assert exc_info.value.claim == "aud"

    def test_null_aud_with_verify_aud_disabled(self, jwt, secret):
        """Token with {"aud": null} should decode when audience verification is disabled."""
        payload = {"some": "payload", "aud": None}
        token = jwt.encode(payload, secret, algorithm="HS256")
        decoded = jwt.decode(
            token,
            secret,
            algorithms=["HS256"],
            options={"verify_aud": False},
        )
        assert decoded["some"] == "payload"

    # --- Consistency: no aud claim behaves the same as null aud ---

    def test_no_aud_without_audience_param(self, jwt, secret):
        """Token without aud claim should decode successfully when no audience is expected."""
        payload = {"some": "payload"}
        token = jwt.encode(payload, secret, algorithm="HS256")
        decoded = jwt.decode(token, secret, algorithms=["HS256"])
        assert decoded["some"] == "payload"
        assert "aud" not in decoded

    def test_no_aud_with_audience_required_raises_missing(self, jwt, secret):
        """Token without aud claim should raise MissingRequiredClaimError when audience is required."""
        payload = {"some": "payload"}
        token = jwt.encode(payload, secret, algorithm="HS256")
        with pytest.raises(MissingRequiredClaimError) as exc_info:
            jwt.decode(token, secret, audience="urn:test", algorithms=["HS256"])
        assert exc_info.value.claim == "aud"

    # --- Normal audience claims still work ---

    def test_valid_string_aud(self, jwt, secret):
        """Token with valid string aud should decode with matching audience."""
        payload = {"some": "payload", "aud": "urn:valid"}
        token = jwt.encode(payload, secret, algorithm="HS256")
        decoded = jwt.decode(token, secret, audience="urn:valid", algorithms=["HS256"])
        assert decoded["aud"] == "urn:valid"

    def test_valid_list_aud(self, jwt, secret):
        """Token with valid list aud should decode with matching audience."""
        payload = {"some": "payload", "aud": ["urn:valid1", "urn:valid2"]}
        token = jwt.encode(payload, secret, algorithm="HS256")
        decoded = jwt.decode(
            token, secret, audience="urn:valid1", algorithms=["HS256"]
        )
        assert decoded["aud"] == ["urn:valid1", "urn:valid2"]

    def test_valid_aud_without_audience_param_raises(self, jwt, secret):
        """Token with valid aud but no audience param should raise InvalidAudienceError."""
        payload = {"some": "payload", "aud": "urn:valid"}
        token = jwt.encode(payload, secret, algorithm="HS256")
        with pytest.raises(InvalidAudienceError):
            jwt.decode(token, secret, algorithms=["HS256"])

    # --- Invalid audience formats still raise appropriate errors ---

    def test_invalid_aud_number_raises(self, jwt, secret):
        """Token with aud=123 should raise InvalidAudienceError."""
        payload = {"some": "payload", "aud": 123}
        token = jwt.encode(payload, secret, algorithm="HS256")
        with pytest.raises(InvalidAudienceError):
            jwt.decode(token, secret, algorithms=["HS256"])

    def test_invalid_aud_empty_string_raises(self, jwt, secret):
        """Token with aud='' should raise InvalidAudienceError (present but invalid)."""
        payload = {"some": "payload", "aud": ""}
        token = jwt.encode(payload, secret, algorithm="HS256")
        with pytest.raises(InvalidAudienceError):
            jwt.decode(token, secret, algorithms=["HS256"])

    def test_invalid_aud_empty_list_raises(self, jwt, secret):
        """Token with aud=[] should raise InvalidAudienceError (present but empty)."""
        payload = {"some": "payload", "aud": []}
        token = jwt.encode(payload, secret, algorithm="HS256")
        with pytest.raises(InvalidAudienceError):
            jwt.decode(token, secret, algorithms=["HS256"])

    # --- Edge cases ---

    def test_null_aud_with_other_claims(self, jwt, secret):
        """Token with null aud and other claims should decode correctly."""
        payload = {"iss": "test", "sub": "123", "aud": None}
        token = jwt.encode(payload, secret, algorithm="HS256")
        decoded = jwt.decode(token, secret, algorithms=["HS256"])
        assert decoded["iss"] == "test"
        assert decoded["sub"] == "123"
        assert decoded["aud"] is None

    def test_null_aud_with_expiry(self, jwt, secret):
        """Token with null aud and exp should decode if not expired."""
        import time
        payload = {"exp": int(time.time()) + 3600, "aud": None}
        token = jwt.encode(payload, secret, algorithm="HS256")
        decoded = jwt.decode(token, secret, algorithms=["HS256"])
        assert decoded["aud"] is None

    def test_null_aud_does_not_affect_other_validation(self, jwt, secret):
        """Null aud should not interfere with other claim validation."""
        payload = {"iss": "test", "aud": None}
        token = jwt.encode(payload, secret, algorithm="HS256")
        # With issuer verification enabled and issuer provided, should succeed
        decoded = jwt.decode(token, secret, issuer="test", algorithms=["HS256"])
        assert decoded["iss"] == "test"
        # With wrong issuer, should fail
        with pytest.raises(Exception):
            jwt.decode(token, secret, issuer="wrong", algorithms=["HS256"])
